# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.74/engra-0.4.74-macos-arm64.tar.gz"
      sha256 "1116a5237434d0c793c7a50756f8c3d7cc6a9bc4be6df2136619573c80500a57"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.74/engra-0.4.74-macos-x64.tar.gz"
      sha256 "ea1264c4ab75e772e31660335eb50e40c0dceaac1aceb3f760cd672ee327c3f9"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.74/engra-0.4.74-linux-arm64.tar.gz"
      sha256 "85f60d8bcdee546743b6047d560cd562181365e5e747eb1925bfc4a56a5f1f39"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.74/engra-0.4.74-linux-x64.tar.gz"
      sha256 "7355feb6aa05c203311fbe132ba758ef919bb2b542e127dec0cf7ae2acef59c7"
    end
  end

  def install
    libexec.install "engra", "_internal"
    if (libexec/"_internal/engra-shim").exist?
      bin.install_symlink libexec/"_internal/engra-shim" => "engra"
    else
      bin.install_symlink libexec/"engra"
    end
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
